  "입니다. 표시·아이콘·사용 패턴은 좌측 [뷰어 — TY Viewer]/[뷰어 — In Viewer] 탭에서 뷰어별로 설정하며, 기능은 두 뷰어 동일합니다.": "Hiển thị·icon·mẫu sử dụng được cài theo từng viewer ở tab [Viewer — TY Viewer]/[Viewer — In Viewer] bên trái; chức năng hai viewer giống nhau.",
  "영상 파이프라인": "Pipeline hình ảnh",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "Pipeline giải mã WASM (beta) — giải mã pixel gốc (WADO-RS bulkdata) ngay trên trình duyệt",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "Khi bật, viewer 2D nhận khung 16bit gốc thay vì render server (JPEG) và giải mã bằng codec WASM. Chỉnh W/L phản ánh ngay không cần vòng server, nhận theo transfer syntax của bệnh viện (JPEG2000/JPEG-LS). Trước khi giải mã sẽ hiển thị bằng render server (tự fallback).",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "Profile chế độ sản phẩm (05 Mode Profile — JSON server)",
