  "같은 환자(차트번호)의 과거 검사에서 고릅니다. 판독 비교의 기본입니다.": "Chọn từ các ca cũ của cùng bệnh nhân (số hồ sơ). Là mặc định của so sánh đọc.",
  "내가 판독했던 검사 전체에서 고릅니다 — 환자가 달라도 됩니다. 내가 이미 판독하며 본 검사만 모집단이라 새로 열리는 자료는 없습니다.": "Chọn từ mọi ca tôi đã đọc — có thể khác bệnh nhân. Chỉ gồm các ca tôi đã xem khi đọc nên không mở ra dữ liệu mới.",
