  "Monitor 띄우기 — 인접 모니터 창 (다음, 끝번이면 이전)": "Mở Monitor — cửa sổ màn hình kế bên (kế tiếp, cuối thì lùi lại)",
  "판독 도크 History의 과거검사(Prior Studies) 썸네일 클릭 시 적용. Monitor 띄우기 예: 모니터 1·2·3에서 3번 기준→2번, 1번 기준→2번에 표시. 조건 미충족(단일 모니터·감지/팝업 차단) 시 Layout 1:2로 폴백. ⇄ Compare(다중 선택)의 다중 모니터 배치는 위 체크가 담당합니다. 창 관리 권한(HTTPS)·팝업 허용 필요.": "Áp dụng khi nhấp thumbnail ca cũ (Prior Studies) trong dock đọc History. Vd Mở Monitor: với màn hình 1·2·3, chuẩn số 3→số 2, chuẩn số 1→số 2. Không đủ điều kiện (một màn hình·chặn phát hiện/popup) thì fallback Layout 1:2. Bố trí nhiều màn hình của ⇄ Compare (chọn nhiều) do ô tích trên đảm nhiệm. Cần quyền quản lý cửa sổ (HTTPS)·cho phép popup.",
  "시스템 단축키": "Phím tắt hệ thống",
  "기본값으로 초기화": "Đặt lại về mặc định",
