  "워크리스트 — 뷰어별 그리드 컬럼 (계정별 저장)": "Worklist — cột lưới theo từng viewer (lưu theo tài khoản)",
  "공통 워크리스트 설정 사용 (기본) — 해제하면 이 뷰어 전용 컬럼 구성을 편집합니다": "Dùng cài đặt worklist chung (mặc định) — bỏ tích để chỉnh cấu hình cột riêng của viewer này",
  "모드로 워크리스트를 열면 이 구성이 공통 설정 대신 적용됩니다. OK(저장) 시 반영.": "mở worklist bằng chế độ này thì cấu hình này được áp dụng thay cài đặt chung. Có hiệu lực khi OK (lưu).",
  "워크리스트 — 구성요소 표시/숨김 (화면 드래그·✕ 와 동기)": "Worklist — hiện/ẩn thành phần (đồng bộ với kéo màn hình·✕)",
  "해제 = 워크리스트에서 숨김. 화면에서 스플리터를 최소까지 드래그하거나 ✕(패널 그립)로 숨긴 상태가 여기와 양방향으로 동기됩니다.": "Bỏ tích = ẩn khỏi worklist. Trạng thái ẩn bằng cách kéo splitter tới mức nhỏ nhất hoặc ✕ (grip bảng) được đồng bộ hai chiều với đây.",
  "그리드 컬럼 구성 — Filter Setting (USE/NO USE, UBPACS형)": "Cấu hình cột lưới — Filter Setting (USE/NO USE, kiểu UBPACS)",
  "USE/NO USE 클릭으로 토글, ▲▼로 표시 순서 변경 — OK(저장) 시 적용.": "Nhấp USE/NO USE để bật/tắt, ▲▼ để đổi thứ tự hiển thị — áp dụng khi OK (lưu).",
