  "체크 해제 시 워크리스트에서 해당 창이 숨겨집니다. 배치 순서는 워크리스트에서 그립(⋮) 드래그로 변경.": "Bỏ tích thì cửa sổ đó bị ẩn khỏi worklist. Đổi thứ tự bằng kéo grip (⋮) trong worklist.",
