  "끄면 워크리스트(⌂ Adv·🌐·우클릭 메뉴)와 뷰어의 OHIF 버튼이 숨겨지고 동작하지 않습니다. 더블클릭 동작이 OHIF 로 설정돼 있어도 자체 뷰어로 열립니다.": "Tắt thì nút OHIF ở worklist (⌂ Adv·🌐·menu chuột phải) và viewer bị ẩn, không hoạt động. Dù nhấp đúp được đặt là OHIF vẫn mở bằng viewer tích hợp.",
  "Tools 아이콘 크기 (TY · In 뷰어)": "Cỡ icon Tools (TY · In viewer)",
