  "이동 대상 환자가 이미 Exam 탭으로 열려 있으면 그 탭으로 전환되고, 아니면 열면서 이동합니다. Worklist·Image Viewer·Reading Viewer는 열린 환자를 서로 따라갑니다(연동). OK(저장) 시 적용.": "Nếu bệnh nhân đích đã mở ở tab Exam thì chuyển sang tab đó, chưa thì mở và chuyển. Worklist·Image Viewer·Reading Viewer theo nhau bệnh nhân đang mở (liên kết). Áp dụng khi OK (lưu).",
  "행잉 프로토콜 저장됨 — 왼쪽 ⟳ Refresh 후 뷰어 재오픈 시 적용": "Đã lưu hanging protocol — áp dụng khi ⟳ Refresh bên trái rồi mở lại viewer",
