  "여기서 정한 것은 기본값입니다. 협진 중에는 협진 페이지에서 참가자마다 켜고 끌 수 있습니다.": "Đây là giá trị mặc định. Trong phiên hội chẩn, bạn có thể bật/tắt cho từng người trên bảng hội chẩn.",
  "판독 수정·영상 삭제는 협진으로 절대 위임되지 않습니다 — 목록에 없는 이유입니다.": "Sửa kết quả đọc và xóa hình ảnh không bao giờ được ủy quyền — vì vậy không có trong danh sách.",
