  "참가자의 권한 요청을 자동 승인": "Tự động duyệt yêu cầu quyền của người tham gia",
  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "Chỉ người trình bày truyền điều khiển màn hình (thu phóng/kéo/W-L). Những người khác xem tự do; chú thích và con trỏ luôn được chia sẻ.",
  "참여자 표시": "Hiển thị người tham gia",
