  "원격 PACS 계정으로 로그인하면 면허·전문의 번호가 자동으로 채워집니다(등록이 없으면 공란).": "Đăng nhập bằng tài khoản PACS từ xa sẽ tự động điền số giấy phép và số chuyên khoa (để trống nếu chưa đăng ký).",
  "무대에 크게 — 이 화면 위에 함께 표시할 수 있습니다": "Mở trên sân khấu — có thể cùng đánh dấu trên màn hình này",
  "내 화면을 전원에게 보여 줍니다 — 지금 발표 중인 사람에게서 넘겨받습니다": "Hiển thị màn hình của bạn cho mọi người — tiếp quản từ người đang trình bày",
