  "표시 = 그리드 컬럼 · 검색 = 검색 필터 바 노출 · 행 드래그/▲▼ = 순서. 그리드 헤더를 드래그해 바꾼 순서와 같은 저장(계정별·뷰어별)이라 서로 그대로 반영됩니다.": "Hiển thị = cột lưới · Tìm kiếm = hiện ở thanh lọc · kéo hàng/▲▼ = thứ tự. Cùng nơi lưu (theo tài khoản·trình xem) với kéo tiêu đề lưới — phản ánh hai chiều.",
  "검색창 설정 — 통합 검색(SEARCH/AI)의 방식·범위": "Ô tìm kiếm — chế độ và phạm vi của tìm kiếm hợp nhất (SEARCH/AI)",
