  "워크리스트 '의뢰 일시' 컬럼의 표시 형식입니다.": "Định dạng hiển thị của cột \"Thời điểm yêu cầu\".",
  "문법: =단어(정확) · 단어%(접두) · !단어(제외) · 공백=다중어. 범위·방식·형식 모두 계정별 저장(로밍)입니다.": "Cú pháp: =từ (chính xác) · từ% (tiền tố) · !từ (loại trừ) · dấu cách = nhiều từ. Phạm vi, chế độ, định dạng lưu theo tài khoản.",
  "⚠ Live(원격 직결)는 원격 PACS 파라미터 한계로 환자 ID/이름에만 통합 검색이 적용됩니다.": "⚠ Ở chế độ Live, tìm kiếm hợp nhất chỉ áp dụng cho ID/tên bệnh nhân do giới hạn tham số PACS từ xa.",
  "SEARCH — 선택한 범위에서 검색 (=정확 / 접두% / !제외 · 공백=다중어)": "SEARCH — tìm trong phạm vi đã chọn (=chính xác / tiền tố% / !loại trừ · dấu cách = nhiều từ)",
  "검색 방식 — SEARCH: 선택한 범위에서 문법 검색(=정확/접두%/!제외/공백=다중어) · AI: 자연어를 필터로 변환": "Chế độ — SEARCH: tìm theo cú pháp trong phạm vi đã chọn · AI: chuyển ngôn ngữ tự nhiên thành bộ lọc",
