  "배정된 판독 대기(요청·재판독·작성중) — 원 서버 집계와 동일, 30초마다 갱신": "Ca đọc được phân công (yêu cầu, đọc lại, đang viết) — trùng số liệu máy chủ gốc, làm mới mỗi 30 giây",
